          camX: Number(d.camX),
          camXSettled: !!d.camXSettled,
          macroLod: !!d.macroLod,
          presentPaused: !!d.presentPaused,
          stillOff: !!(el && el.getAttribute("data-s1r-offcenter") === "1"),
