        const k = Number(d.camK);
        if (!Number.isFinite(k) || !Number.isFinite(macroK)) return false;
        const dk = Math.abs(k - macroK);
        // First soft-capped exit step toward micro k.
        return dk > 0.05 && dk <= 0.45 + 0.06;
