        camX: Number(d.camX),
        camY: Number(d.camY),
        camK: Number(d.camK),
        ratio: Number(d.scrollRatio) || 0,
        macroLod: !!d.macroLod,
        presentPaused: !!d.presentPaused,
        cfgUnroll: Number(d.cfgUnroll) || 0,
        macroAttr: (vp && vp.getAttribute("data-scroll-macro")) || "",
        targetNodeId: d.targetNodeId || "",
