        row.className = "src-line";
        row.setAttribute("data-s1v", "1");
        row.setAttribute("data-s1v-ln", String(ln));
        row.innerHTML = '<span class="ln">' + ln + '</span><span class="tx">' + tx + "</span>";
        body.appendChild(row);
        return row;
